\mathsf{Rule}_{same}
=
\{((a\approx b,C(a)),C(b)):C\in\mathsf{Cls}_{DL},\ a,b\in N_I\}
\cup
\{((a\approx b,R(a,c)),R(b,c)):R\in\mathsf{ORole},\ a,b,c\in N_I\}
\cup
\{((a\approx b,R(c,a)),R(c,b)):R\in\mathsf{ORole},\ a,b,c\in N_I\}.

\mathsf{Rule}_{clash}
=
\{((\operatorname{Dis}(C,D),C(a),D(a)),\bot_{\Omega}):
C,D\in\mathsf{Cls}_{DL},\ a\in N_I\}
\cup
\{((a\approx b,a\not\approx b),\bot_{\Omega}):a,b\in N_I\}
\cup
\{((C(a),(\neg C)(a)),\bot_{\Omega}):
C\in\mathsf{Cls}_{DL},\ a\in N_I\}.

\mathsf{Rule}_{data}
=
\{((U(a,\ell),\Delta(\ell)),(\exists U.\Delta)(a)):U\in N_D,\Delta\in\mathsf{DRange},a\in N_I,\ell\in N_L\}
\cup
\{(((\forall U.\Delta)(a),U(a,\ell)),\Delta(\ell)):U\in N_D,\Delta\in\mathsf{DRange},a\in N_I,\ell\in N_L\}
